const float sharpness = 7.;

// adapted from gaussian blur from https://www.shadertoy.com/view/MdtXWr by bmolynea
const int   filterSize    = 7;  // must be odd

const int   halfFilterSize = filterSize / 2;

float Gaussian (float x, float sigma)
{
    return exp(-(x*x) / (2.0 * sigma*sigma));
}

vec3 SharpenPixel ( vec2 uv, float sharpenStrength )
{
    float sigmaSharp = .01;
    float sigmaBlurred = 1.4;

    float totalSharp = 0.0;
    float totalBlurred = 0.0;
    vec3 retSharp = vec3(0);
    vec3 retBlurred = vec3(0);

    vec2 pixelSize = 1.0 / iResolution.xy;

    for (int iy = 0; iy < filterSize; iy++)
    {
        float fySharp = Gaussian (float(iy) - float(halfFilterSize), sigmaSharp);
        float fyBlurred = Gaussian (float(iy) - float(halfFilterSize), sigmaBlurred);

        float offsety = float(iy-halfFilterSize) * pixelSize.y;

        for (int ix = 0; ix < filterSize; ix++)
        {
            float fxSharp = Gaussian (float(ix) - float(halfFilterSize), sigmaSharp);
            float fxBlurred = Gaussian (float(ix) - float(halfFilterSize), sigmaBlurred);

            float offsetx = float(ix-halfFilterSize) * pixelSize.x;

            float fSharp = fxSharp*fySharp;
            float fBlurred = fxBlurred*fyBlurred;
            totalSharp += fSharp;
            totalBlurred += fBlurred;
            vec3 tap = texture(iChannel0, uv + vec2(offsetx, offsety)).rgb;
            retSharp += tap * fSharp;
            retBlurred += tap * fBlurred;
        }
    }
    retSharp /= totalSharp;
    retBlurred /= totalBlurred;
    return clamp( retSharp + (retSharp-retBlurred)*sharpenStrength, 0., 1. );
}



void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    ivec2 dynamicResolutionDataUV = ivec2(iResolution.xy)-1;
    int resolutionScaling = int( floor( texelFetch( iChannel0, dynamicResolutionDataUV, 0 ).y ) );

//    fragColour = texelFetch(iChannel0,ivec2(fragCoord)/resolutionScaling,0);

    fragColour.rgb = SharpenPixel( (fragCoord/iResolution.xy)/float(resolutionScaling), sharpness );
    fragColour.a = 1.;

    float grey = fragColour.r; // more interesting contrast in this channel

    vec2 tones = vec2(.1,.6);
    grey = (grey-tones.x)/(tones.y-tones.x);//smoothstep(tones.x,tones.y,grey);
    grey= max(grey,0.);

    grey = pow(grey,1.5);

    // step is greater/equal, we want greater so flip it (otherwise blacks aren't solid black)
    float bnw = 1.-step( grey, texelFetch(iChannel1,(ivec2(fragCoord)/resolutionScaling)%ivec2(iChannelResolution[1].xy),0).g );

    fragColour.rgb = vec3(bnw);
}

const float TARGET_RESOLUTION_Y = 300.; // i set this low to show off the dithering

vec2 quasi2 = vec2(.754877666247,.569840290998);
vec3 quasi3 = vec3(0.8191725,0.6710436,0.5497005);

float Noise( vec3 pos )
{
    return texture(iChannel1,pos/32.).r*2.-1.;
}

float GroundSDF( vec3 pos, int octaves )
{
    float f = 0.;

    float s = 1.4;
    vec3 p = pos * s * .1;

    for ( int i = 0; i < octaves; i++ )
    {
        //f = mix(f,1.,abs(Noise(p))*s);
        f += abs(Noise(p))*s;
        p = vec3(p.z*5.,p.xy*3.+p.yx*4.*vec2(1,-1))*2./5.;
        s /= 2.;
    }

    return (pos.y + f) * .8;
}

float FogDensity( vec3 pos, int octaves )
{
    float f = 0.;
    float s = 1.; // Don't change
    vec3 p = pos * .7;

    p += iTime*vec3(0,-.02,.02);

    for ( int i = 0; i < octaves; i++ )
    {
        f += Noise(p)*s;
        p = vec3(p.z*5.,p.xy*3.+p.yx*4.*vec2(1,-1))*2./5.;
        s /= 1.7; // lower = stronger details
    }

    // add a low layer
    f += smoothstep(.2,.0,abs(pos.y+1.))*.4;

    // add a cloud layer
    f += smoothstep(.4,.2,abs(pos.y-.3))*.7;

//    f = smoothstep(-.3,1.5,f); // bigger clouds
    f = smoothstep(.2,1.5,f); // smaller clouds
//    f = smoothstep(-.2,3.,f); // softer clouds

    float g = GroundSDF(pos,2);
    f *= 1.-g/(abs(g)+.04);

    return f*1.; // Modulate density here instead
}

float AirDensity( vec3 pos )
{
    return exp2(-pos.y/5.-3.);
}


void mainImage( out vec4 fragColour, in vec2 _fragCoordIn )
{
    ivec2 dynamicResolutionDataUV = ivec2(iResolution.xy)-1;

    if ( int(_fragCoordIn.x) == dynamicResolutionDataUV.x &&
         int(_fragCoordIn.y) == dynamicResolutionDataUV.y )
    {
        float resolutionScalingF = texelFetch( iChannel0, dynamicResolutionDataUV, 0 ).x;
        float lastResolutionScalingF = resolutionScalingF;

        if ( iFrame == 0 ) resolutionScalingF = 1.0;

        resolutionScalingF = max( 1., floor(iResolution.y/TARGET_RESOLUTION_Y + .5) );

        fragColour = vec4(resolutionScalingF,lastResolutionScalingF,0,1);

        return;
    }

    vec4 resolutionData = texelFetch( iChannel0, dynamicResolutionDataUV, 0 );
    float resolutionScaling = floor( resolutionData.x );
    float lastResolutionScaling = floor( resolutionData.y );

    vec2 fragCoord = _fragCoordIn * resolutionScaling;

    if ( fragCoord.x > iResolution.x+7. || fragCoord.y > iResolution.y+7. ) { fragColour = vec4(1); return;  }// added overrun for sharpen filter

    float time = iTime*.2; // I want a fairly static shot with enough movement to break up the aliasing
    vec3 velocity = vec3(1.0,0,0);

    float zoom = 1.;
    vec3 camPos = vec3(sin(time*.618)*.4,-.3+.1*sin(time),0) + time*velocity;
    vec3 camLook = vec3(-1,-.5,4) + (time-sin(time))*velocity;

    float jitterSeed = fract(
                            dot(quasi2.yx,fragCoord)
                            + texelFetch(iChannel1,ivec3(fragCoord,0)&31,0).r * .2
                        );
    vec2 jitter = fract(quasi2*(float(iFrame) + jitterSeed)); // ideal precession per point to give maximum coverage as fast as possible
    vec3 ray = vec3((fragCoord+jitter-iResolution.xy*.5)/(iResolution.x*zoom),1.);
    vec3 camDir = normalize(camLook-camPos);
    vec3 camRight = normalize(cross(vec3(0,1,0),camDir));
    vec3 camUp = cross(camDir,camRight);

    ray = ray.x*camRight + ray.y*camUp + ray.z*camDir;

    // depth of field
    float focalDepth = 4.;
    float aperture = .003;
    camPos += ray*focalDepth; // rely on ray.z = 1 before transform 
    ray += ((jitter.y*2.-1.)*camRight + (jitter.x*2.-1.)*camUp)*aperture;
    camPos -= ray*focalDepth;

    ray = normalize(ray);

    vec3 sunDir = normalize(vec3(-3,2,1));


    /*
    march against the ground
    BUT with a maximum step size dictated by volumetric quality
    accumulate volumetric occlusion with emissive absorbant fog
    ground intersection picks a neutral dark ground colour - emphasis is on atmospherics
    */
    vec3 pos = camPos;
    vec3 absorption = vec3(1);
    vec3 emission = vec3(0);
    float lastStride = 0.;
    float lastFogDensity = 0.;
    float lastAirDensity = 0.;
    for ( int i=0; i < 200; i++ )
    {
        float h = GroundSDF( pos, 6 );

        // accumulate fog occlusion
        float fogDensity = FogDensity(pos,6);
        float fogIntegral = lastStride*mix(fogDensity,lastFogDensity,.5);

        float airDensity = AirDensity(pos);
        float airIntegral = lastStride*mix(airDensity,lastAirDensity,.5);

        vec3 fogAbsorptionDelta = pow( vec3(0.1), vec3(fogIntegral) );
        vec3 fogEmissionDelta = (1.-pow( vec3(0.1), vec3(fogIntegral) ));

        // fog lighting - just sample toward light and subtract
        float shadowStep = .07;
        float shadow = (fogDensity - FogDensity(pos+sunDir*shadowStep,3))/shadowStep;
        fogEmissionDelta *= mix(vec3(.2,.27,.35)*.4,vec3(1)*.6,smoothstep(-1.,1.,shadow));

        vec3 airAbsorptionDelta = pow( 1.-vec3(.3,.48,.7), vec3(airIntegral) );
        vec3 airEmissionDelta = (1. - pow( 1.-vec3(.4,.55,.7), vec3(airIntegral) )) * vec3(.6);

        vec3 absorptionDelta = fogAbsorptionDelta * airAbsorptionDelta;
        emission += (absorption*sqrt(absorptionDelta)) * (fogEmissionDelta + airEmissionDelta);
        absorption *= absorptionDelta;

        lastFogDensity = fogDensity;
        lastAirDensity = airDensity;

        h = min(h,.1); // fog step
        lastStride = h;

        pos += h*ray;
        if ( h < .001 ) break;
    }

    // do some lighting on the terrain
    vec2 d = vec2(-1,1)*.02; // big enough to avoid most of the aliasing in the noise texture
    vec3 normal = normalize(
                        GroundSDF( pos + d.xxx, 6 )*d.xxx +
                        GroundSDF( pos + d.xyy, 6 )*d.xyy +
                        GroundSDF( pos + d.yxy, 6 )*d.yxy +
                        GroundSDF( pos + d.yyx, 6 )*d.yyx
                    );

    float aostep = .3;
    float ao = smoothstep(-.2,1.5,GroundSDF( pos + normal*aostep, 6 )/aostep);

    fragColour.rgb = vec3(.5)*ao + vec3(.5)*max(dot(normal,sunDir),0.); //vec3(.03);//fract(pos);
    fragColour.rgb *= .4*mix( vec3(.0,.2,.0), vec3(.07,.1,0)+.3, smoothstep(.3,.9,ao) ); // albedo

    if ( GroundSDF( pos, 6 ) > .5 ) fragColour.rgb = vec3(.14);

    fragColour.rgb = fragColour.rgb*absorption + emission;

    fragColour.rgb = mix( texelFetch(iChannel0,ivec2(_fragCoordIn*resolutionScaling/lastResolutionScaling),0).rgb, fragColour.rgb, .3 );

    fragColour.a = 1.;
}
